class Node:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next


class MyLinkedList:
    def __init__(self):
        self.dummy = Node()
        self.size = 0

    def get(self, index):
        if index < 0 or index >= self.size:
            return -1
        curr = self.dummy.next
        for _ in range(index):
            curr = curr.next
        return curr.val

    def addAtHead(self, val):
        self.addAtIndex(0, val)

    def addAtTail(self, val):
        self.addAtIndex(self.size, val)

    def addAtIndex(self, index, val):
        if index > self.size:
            return
        index = max(index, 0)
        prev = self.dummy
        for _ in range(index):
            prev = prev.next
        prev.next = Node(val, prev.next)
        self.size += 1

    def deleteAtIndex(self, index):
        if index < 0 or index >= self.size:
            return
        prev = self.dummy
        for _ in range(index):
            prev = prev.next
        prev.next = prev.next.next
        self.size -= 1


def run_linked_list_ops(ops):
    ll = MyLinkedList()
    output = []
    for op in ops:
        name = op[0]
        if name == 'get':
            output.append(ll.get(op[1]))
        elif name == 'addAtHead':
            ll.addAtHead(op[1])
        elif name == 'addAtTail':
            ll.addAtTail(op[1])
        elif name == 'addAtIndex':
            ll.addAtIndex(op[1], op[2])
        elif name == 'deleteAtIndex':
            ll.deleteAtIndex(op[1])
    return output

